<?php
declare(strict_types=1);require_once dirname(__DIR__).'/src/bootstrap.php';Auth::requireOwner();
if(($_SERVER['REQUEST_METHOD']??'GET')==='POST'){
    Auth::verifyCsrf();
    try{
        $op=(string)($_POST['op']??'');
        if($op==='run'){$r=FreeModelScoutService::run('owner_manual');$_SESSION['flash']='خلصت دورة نور: '.(int)($r['models_found']??0).' موديل مرصود، '.(int)($r['providers_working']??0).' مزود شغال.';$_SESSION['flash_type']=($r['state']??'')==='completed'?'success':'warning';}
        elseif($op==='toggle'){put_setting('free_model_scout.enabled',!empty($_POST['enabled'])?'1':'0');$_SESSION['flash']='تم تحديث تشغيل نور اليومي.';$_SESSION['flash_type']='success';}
        elseif($op==='route_toggle'){$pk=trim((string)($_POST['provider_key']??''));db()->prepare('UPDATE free_provider_candidates SET auto_route=? WHERE provider_key=?')->execute([!empty($_POST['auto_route'])?1:0,$pk]);$_SESSION['flash']='تم تحديث استخدام المزود في الـFallback.';$_SESSION['flash_type']='success';}
        else throw new RuntimeException('free_model_scout_action_invalid');
    }catch(Throwable $e){$_SESSION['flash']=AdminUi::humanError(Security::redactSecrets($e->getMessage(),240));$_SESSION['flash_type']='error';}
    header('Location: /api/admin/free-model-scout.php');exit;
}
$d=FreeModelScoutService::dashboard();$s=(array)$d['summary'];AdminUi::header('نور — صياد الموديلات المجانية','free_model_scout');echo AdminUi::flash();
?>
