<div class="metric-grid metric-grid-4"><?=AdminUi::stat('الموديلات المرصودة',(int)$s['models'],'نشطة في الكتالوج')?><?=AdminUi::stat('موديلات شغالة',(int)$s['working_models'],'حسب آخر صحة للمزود')?><?=AdminUi::stat('مزودات شغالة',(int)$s['working_providers'],'Fallback متاح')?><?=AdminUi::stat('تحتاج تدخل',(int)$s['human_required'],'تسجيل/مفتاح يدوي')?></div>
